package com.afs.guard;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.atomic.*;import org.json.*;

/** Emulator fixtures only. Actual window screenshots and hardware canvases, no manual Canvas substitute. */
public final class RuntimeAcceptanceDeviceTest extends Instrumentation {
 int checks;final List<Activity> pages=new ArrayList<>();final StringBuilder details=new StringBuilder();
 void check(boolean ok,String label){checks++;if(!ok)throw new AssertionError(label);}
 void main(Runnable r){Throwable[] error={null};runOnMainSync(()->{try{r.run();}catch(Throwable e){error[0]=e;}});if(error[0]!=null)throw new AssertionError(error[0]);}
 Object field(Object o,String name){try{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}catch(Exception e){throw new RuntimeException(e);}}
 void set(Object o,String name,Object value){try{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);f.set(o,value);}catch(Exception e){throw new RuntimeException(e);}}
 void call(Object o,String name,Class<?>[] types,Object...args){try{Method m=o.getClass().getDeclaredMethod(name,types);m.setAccessible(true);m.invoke(o,args);}catch(Exception e){throw new RuntimeException(e);}}
 Activity open(Class<?> type){ActivityMonitor monitor=addMonitor(type.getName(),null,false);main(()->getTargetContext().startActivity(new Intent(getTargetContext(),type).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_MULTIPLE_TASK)));Activity a=waitForMonitorWithTimeout(monitor,8000);removeMonitor(monitor);check(a!=null,"opens "+type.getSimpleName());pages.add(a);return a;}
 void waitFor(java.util.function.BooleanSupplier test,String label)throws Exception{for(int i=0;i<250&&!test.getAsBoolean();i++){main(()->{});Thread.sleep(20);}check(test.getAsBoolean(),label);}
 void restore(SharedPreferences p,String key,Object v){SharedPreferences.Editor e=p.edit();if(v==null)e.remove(key);else if(v instanceof String)e.putString(key,(String)v);else if(v instanceof Boolean)e.putBoolean(key,(Boolean)v);e.commit();}
 static final class Picture extends FrameLayout {volatile boolean hardware;final MemoryImageView image;Picture(Context c,String n,JSONArray masks){super(c);image=new MemoryImageView(c,n,masks,false);addView(image,new FrameLayout.LayoutParams(-1,-1));}protected void dispatchDraw(Canvas canvas){hardware|=canvas.isHardwareAccelerated();super.dispatchDraw(canvas);}void reveal(){image.reveal();}}
 Object pictureField(Picture v,String n){try{Field f=MemoryImageView.class.getDeclaredField(n);f.setAccessible(true);return f.get(v.image);}catch(Exception e){throw new RuntimeException(e);}}
 Bitmap shot(String name)throws Exception{Bitmap b=getUiAutomation().takeScreenshot();check(b!=null,"actual composed screenshot "+name);try(OutputStream out=new FileOutputStream(new File(getTargetContext().getExternalFilesDir(null),name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}return b;}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){Bundle result=new Bundle();Context c=getTargetContext();SharedPreferences notes=c.getSharedPreferences("afs_guard",0),library=c.getSharedPreferences("afs_memo_library",0),setup=c.getSharedPreferences("afs_setup",0);Object oldNotes=notes.getAll().get("memos_v1"),oldGuide=setup.getAll().get("guide_v1_seen");Map<String,?> oldLibrary=new HashMap<>(library.getAll());File image=null;
 try{check(Build.MODEL.toLowerCase().contains("sdk"),"owned emulator required");setup.edit().putBoolean("guide_v1_seen",true).commit();
  List<MemoStore.Note> fixtures=new ArrayList<>();for(int i=0;i<120;i++)fixtures.add(new MemoStore.Note("runtime-"+i,"QA note "+i,"fixed body for scrolling and filtering "+i,1700000000000L+i,false));notes.edit().putString("memos_v1",MemoStore.toJson(fixtures)).commit();MemoLibrary.setGrid(c,false);
  Activity memo=open(MemoActivity.class);ScrollView scroll=(ScrollView)field(memo,"listScroll");waitFor(()->scroll.getHeight()>0,"memo layout ready");main(()->{check(((List<?>)field(memo,"notes")).size()==120,"120 row fixture loaded");scroll.scrollTo(0,1100);});Thread.sleep(100);int keep=scroll.getScrollY();check(keep>0,"long list reaches offscreen rows");main(()->call(memo,"refreshList",new Class<?>[]{}));Thread.sleep(150);check(Math.abs(scroll.getScrollY()-keep)<3,"refresh keeps reading position");
  main(()->{set(memo,"query","QA note 119");call(memo,"refreshList",new Class<?>[]{boolean.class},true);check(((List<?>)field(memo,"notes")).size()==1,"filter selects exact fixture");});Thread.sleep(100);check(scroll.getScrollY()==0,"filter begins at top");main(()->{set(memo,"query","");call(memo,"refreshList",new Class<?>[]{boolean.class},true);});Thread.sleep(100);
  final int[] xy=new int[2];main(()->scroll.getLocationOnScreen(xy));int x=xy[0]+scroll.getWidth()*3/5,startY=xy[1]+scroll.getHeight()*4/5,endY=xy[1]+scroll.getHeight()/5;AtomicInteger releasedAt=new AtomicInteger(-1);main(()->scroll.setOnTouchListener((view,event)->{if(event.getActionMasked()==MotionEvent.ACTION_UP)releasedAt.set(scroll.getScrollY());return false;}));
  try(InputStream input=new ParcelFileDescriptor.AutoCloseInputStream(getUiAutomation().executeShellCommand("input swipe "+x+" "+startY+" "+x+" "+endY+" 180"))){byte[] buffer=new byte[1024];while(input.read(buffer)!=-1){}}
  Thread.sleep(250);check(releasedAt.get()>0,"real pointer drag scrolls long list");details.append("scrollAtUp=").append(releasedAt).append(" scrollAfter250ms=").append(scroll.getScrollY()).append('\n');check(scroll.getScrollY()>releasedAt.get(),"inertia advances after real pointer release");main(()->scroll.setOnTouchListener(null));main(()->{scroll.fling(0);scroll.scrollTo(0,900);});Thread.sleep(80);int beforeRecreate=scroll.getScrollY();AtomicReference<Activity> replacement=new AtomicReference<>();Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks observer=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){if(a instanceof MemoActivity&&a!=memo)replacement.set(a);}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(observer);try{main(memo::recreate);waitFor(()->replacement.get()!=null,"real Activity recreation");}finally{app.unregisterActivityLifecycleCallbacks(observer);}Activity renewed=replacement.get();pages.add(renewed);Thread.sleep(250);ScrollView newScroll=(ScrollView)field(renewed,"listScroll");check(Math.abs(newScroll.getScrollY()-beforeRecreate)<3,"recreation restores scroll position");
  image=MemoryStore.media(c,"runtime-"+UUID.randomUUID()+".jpg");image.getParentFile().mkdirs();Bitmap raw=Bitmap.createBitmap(4096,3072,Bitmap.Config.ARGB_8888);new Canvas(raw).drawColor(Color.GREEN);try(OutputStream out=new FileOutputStream(image)){raw.compress(Bitmap.CompressFormat.JPEG,90,out);}raw.recycle();String name=image.getName();Activity host=open(MainActivity.class);FrameLayout frame=new FrameLayout(host);Picture picture=new Picture(host,name,new JSONArray().put(new JSONArray("[0.25,0.25,0.5,0.5]")));main(()->{host.setContentView(frame);frame.addView(picture,new FrameLayout.LayoutParams(600,600));});waitFor(()->pictureField(picture,"bitmap")!=null&&picture.hardware,"sampled image draws on hardware canvas");Thread.sleep(120);
  int[] origin=new int[2];main(()->picture.getLocationOnScreen(origin));Bitmap masked=shot("runtime-image-masked");int pixel=masked.getPixel(origin[0]+300,origin[1]+300);check(Color.blue(pixel)>100&&Color.green(pixel)<180,"hardware screenshot contains mask");masked.recycle();main(picture::reveal);Thread.sleep(150);Bitmap revealed=shot("runtime-image-revealed");pixel=revealed.getPixel(origin[0]+300,origin[1]+300);check(Color.green(pixel)>200&&Color.blue(pixel)<50,"hardware screenshot reveals original image");revealed.recycle();
  Bitmap decoded=(Bitmap)pictureField(picture,"bitmap");check(decoded.getAllocationByteCount()<=4*1024*1024,"4096x3072 sampled image bounded to display");details.append("singleDecodedBytes=").append(decoded.getAllocationByteCount()).append('\n');
  Bitmap beforeHidden=(Bitmap)pictureField(picture,"bitmap");main(()->host.moveTaskToBack(true));waitFor(()->picture.getWindowVisibility()!=View.VISIBLE,"image window actually hidden");main(()->picture.setLayoutParams(new FrameLayout.LayoutParams(320,240)));main(()->c.startActivity(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_REORDER_TO_FRONT)));waitFor(()->picture.getWindowVisibility()==View.VISIBLE&&picture.getWidth()==320&&pictureField(picture,"task")==null&&pictureField(picture,"bitmap")!=null&&pictureField(picture,"bitmap")!=beforeHidden,"hidden resize loads new bitmap generation after foreground");main(()->{check(picture.getWidth()==320,"resize reaches actual view");check(((Bitmap)pictureField(picture,"bitmap")).getAllocationByteCount()<=1048576,"hidden resize redecodes to new display sample size");frame.removeView(picture);frame.addView(picture,new FrameLayout.LayoutParams(600,600));});waitFor(()->pictureField(picture,"bitmap")!=null,"detach reattach decodes current generation");
  AtomicBoolean sampling=new AtomicBoolean(true);AtomicLong maxJava=new AtomicLong(),maxPss=new AtomicLong();Thread sampler=new Thread(()->{while(sampling.get()){Runtime rt=Runtime.getRuntime();maxJava.accumulateAndGet(rt.totalMemory()-rt.freeMemory(),Math::max);Debug.MemoryInfo info=new Debug.MemoryInfo();Debug.getMemoryInfo(info);maxPss.accumulateAndGet(info.getTotalPss(),Math::max);SystemClock.sleep(20);}});sampler.start();List<Picture> burst=new ArrayList<>();try{main(()->{frame.removeAllViews();for(int i=0;i<8;i++){Picture p=new Picture(host,name,new JSONArray());burst.add(p);frame.addView(p,new FrameLayout.LayoutParams(600,600));}});for(Picture p:burst)waitFor(()->pictureField(p,"bitmap")!=null,"bounded queue eventually loads each visible owner");long allocations=0;for(Picture p:burst)allocations+=((Bitmap)pictureField(p,"bitmap")).getAllocationByteCount();details.append("eightDecodedBytes=").append(allocations).append('\n');main(frame::removeAllViews);for(Picture p:burst)check(pictureField(p,"task")==null&&pictureField(p,"bitmap")==null,"detach clears owner work and bitmap");}finally{sampling.set(false);sampler.join(1500);}details.append("sampledMaxJavaBytes=").append(maxJava).append(" sampledMaxTotalPssKb=").append(maxPss).append(" sampleIntervalMs=20 (observed maximum, not guaranteed instantaneous peak)\n");
  result.putString("stream","Runtime acceptance device: "+checks+" checks passed\n"+details);
 }catch(Throwable error){result.putString("stream",android.util.Log.getStackTraceString(error)+details);}
 finally{Collections.reverse(pages);for(Activity a:pages)main(a::finish);restore(notes,"memos_v1",oldNotes);restore(setup,"guide_v1_seen",oldGuide);SharedPreferences.Editor e=library.edit().clear();for(Map.Entry<String,?> pair:oldLibrary.entrySet()){Object v=pair.getValue();if(v instanceof String)e.putString(pair.getKey(),(String)v);else if(v instanceof Boolean)e.putBoolean(pair.getKey(),(Boolean)v);else if(v instanceof Long)e.putLong(pair.getKey(),(Long)v);}e.commit();if(image!=null)image.delete();}
 finish(result.getString("stream","").startsWith("Runtime acceptance device:")?-1:0,result);
 }
}




